local old_addEventHandler = addEventHandler
addEventHandler = function(name, cb)
    if name == "onReceivePacket" or name == "onSendPacket" then
        old_addEventHandler(name, function(id, bs)
            if name == "onReceivePacket" and id == 220 and not (isAutomatingSport or isAutomatingDrift) then return end
            local ok, res = pcall(cb, id, bs)
            if ok then return res end
        end)
    else
        old_addEventHandler(name, cb)
    end
end

package.loaded['arizona-events'] = nil
local ae = require 'arizona-events'
addEventHandler = old_addEventHandler

pcall(function()
    ffi.cdef[[
        void* LoadLibraryA(const char* lpLibFileName);
        void* GetProcAddress(void* hModule, const char* lpProcName);
        int   FreeLibrary(void* hModule);
        int __thiscall GetBonePosition(void* ped, float* outVec, int boneId, bool update);
    ]]
end)
local kernel32 = ffi.load('kernel32')
local getBonePosition = ffi.cast("int (__thiscall*)(void*, float*, int, bool)", 0x5E4280)

local function getBodyPartCoordinates(id, handle)
    local pedptr = getCharPointer(handle)
    local vec = ffi.new("float[3]")
    getBonePosition(ffi.cast("void*", pedptr), vec, id, true)
    return vec[0], vec[1], vec[2]
end

local function getGameStamina()
    local float = memory.getfloat(0xB7CDB4)
    return math.floor(float/31.47000244)
end

